const items = $input.all();
let extractedText = '';

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (item.binary) {
    for (const key of Object.keys(item.binary)) {
      const b = item.binary[key];
      const fn = (b.fileName || '').toLowerCase();
      if (fn.includes('document.xml')) {
        let xmlStr = '';
        try {
          if (this.helpers && this.helpers.getBinaryDataBuffer) {
            const buf = await this.helpers.getBinaryDataBuffer(i, key);
            xmlStr = buf.toString('utf8');
          }
        } catch(e) {}

        if (!xmlStr && b.data && b.data !== 'filesystem-v2') {
          try {
            xmlStr = Buffer.from(b.data, 'base64').toString('utf8');
          } catch(e) {}
        }

        if (xmlStr) {
          extractedText = xmlStr
            .replace(/<\/w:p>/gi, '\n')
            .replace(/<[^>]+>/g, ' ')
            .replace(/[ \t]+/g, ' ')
            .replace(/\n\s+/g, '\n')
            .trim();
          break;
        }
      }
    }
  }
  if (extractedText) break;
}

return [{
  json: { text: extractedText || 'No text extracted from DOCX' }
}];

let parsed = {};

if ($json.document_title || $json.document_summary || $json.document_category) {
  parsed = { ...$json };
} else {
  const raw = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) ||
              ($json.body && $json.body.choices && $json.body.choices[0] && $json.body.choices[0].message && $json.body.choices[0].message.content) ||
              $json.text ||
              $json.response || '';
  if (raw) {
    try {
      parsed = JSON.parse(raw.trim());
    } catch (e) {
      try {
        const match = raw.match(/\{[\s\S]*\}/);
        if (match) {
          parsed = JSON.parse(match[0]);
        }
      } catch (e2) {
        parsed = {};
      }
    }
  }
}

let summaryText = parsed.document_summary || $json.document_summary || '• Document uploaded and filed in case vault.';
if (Array.isArray(summaryText)) {
  summaryText = summaryText.map(pt => pt.startsWith('•') ? pt : '• ' + pt).join('\n');
} else if (typeof summaryText === 'string') {
  const lines = summaryText.split('\n').filter(l => l.trim().length > 0);
  summaryText = lines.map(l => l.trim().startsWith('•') ? l.trim() : '• ' + l.trim()).join('\n');
}

const driveNode = $('Upload to Google Drive Vault').first();
const driveUrl = driveNode && driveNode.json ? (driveNode.json.webViewLink || ('https://drive.google.com/file/d/' + driveNode.json.id + '/view')) : '';
const caseData = $('Execute Workflow Trigger').first().json;

return [
  {
    json: {
      case_id: caseData.case_id,
      client_name: caseData.client_name,
      client_email: caseData.client_email,
      location: caseData.location,
      address: caseData.address,
      pincode: caseData.pincode,
      case_status: caseData.case_status,
      legal_proceeding_stage: caseData.legal_proceeding_stage,
      document_url: driveUrl,
      document_title: parsed.document_title || $json.document_title || 'Legal Notice / Filing',
      document_category: parsed.document_category || $json.document_category || 'Statutory Notice',
      document_summary: summaryText,
      urgency_level: parsed.urgency_level || $json.urgency_level || 'Medium',
      adverse_party: parsed.adverse_party || $json.adverse_party || 'None'
    }
  }
];

const caseData = $('Execute Workflow Trigger').first().json;

return [{
  json: {
    case_id: caseData.case_id,
    client_name: caseData.client_name,
    client_email: caseData.client_email,
    location: caseData.location,
    address: caseData.address,
    pincode: caseData.pincode,
    case_status: caseData.case_status,
    legal_proceeding_stage: caseData.legal_proceeding_stage,
    document_url: '',
    document_title: 'No Document Attached',
    document_category: 'General Matter',
    document_summary: 'Initial intake completed without attached case documents.',
    urgency_level: 'Medium',
    adverse_party: 'None',
    jotter_url: ''
  }
}];

const incomingJson = $input.first().json;
let origBinary = null;
try {
  origBinary = $('Execute Workflow Trigger').first().binary?.Attach_Case_Document___Notice;
} catch (e) {
  origBinary = null;
}

if (!origBinary) {
  return [{ json: incomingJson }];
}

const binCopy = { ...origBinary };
const fn = (binCopy.fileName || incomingJson.name || '').toLowerCase();
if (fn.endsWith('.docx')) {
  binCopy.fileExtension = 'zip';
  binCopy.mimeType = 'application/zip';
  binCopy.fileName = (binCopy.fileName || 'document.docx').replace(/\.docx$/i, '.zip');
}

return [{
  json: incomingJson,
  binary: {
    Attach_Case_Document___Notice: binCopy
  }
}];

