const triage = $('Parse AI Triage Output').first().json;
const driveDoc = $('Create Jotter Document').first().json;
const jotterId = driveDoc.id;
const jotterUrl = driveDoc.webViewLink || ('https://drive.google.com/file/d/' + jotterId + '/view');

return [{
  json: {
    ...triage,
    jotter_url: jotterUrl
  }
}];

const item = $input.first();
let text = '';
try {
  if (item.binary && item.binary.Attach_Case_Document___Notice) {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'Attach_Case_Document___Notice');
    text = buf.toString('utf8');
  }
} catch (e) {
  try {
    if (item.binary && item.binary.Attach_Case_Document___Notice && item.binary.Attach_Case_Document___Notice.data) {
      text = Buffer.from(item.binary.Attach_Case_Document___Notice.data, 'base64').toString('utf8');
    }
  } catch (e2) {}
}

return [{ json: { text: text || 'No text extracted from TXT file' } }];
